@Transactional
    public UserEntity registerDoctor(NewDoctorDTO dto, MultipartFile licenseImage) {
        if (userRepository.findByEmail(dto.getEmail()).isPresent()) {
            throw new DuplicateResourceException(ErrorCodeENUM.EMAIL_ALREADY_EXISTS);
        }

        Optional<UserEntity> phoneCheck = userRepository.findByEmailOrNumber(dto.getNumber());
        if (phoneCheck.isPresent()) {
            throw new DuplicateResourceException(ErrorCodeENUM.NUMBER_ALREADY_EXISTS);
        }

        if (doctorProfileRepository.findByLicenseNumber(dto.getLicenseNumber()).isPresent()) {
            throw new DuplicateResourceException(ErrorCodeENUM.LICENSE_ALREADY_EXISTS);
        }

        CountriesEntity country = countriesRepository.findById(dto.getCountryId()).orElseThrow(() -> new ResourceNotFoundException(ErrorCodeENUM.COUNTRY_NOT_FOUND));

        String imageUrl;
        try {
            imageUrl = fileUploadService.uploadFile(licenseImage);
        } catch (IOException e) {
            throw new RuntimeException("No se pudo obtener la URL de la imagen de Cloudinary.");
        }

        String hashedPassword = passwordEncoder.encode(dto.getPassword());
        RoleEntity role = roleRepository.findByName(RoleENUM.DOCTOR).orElseThrow(() -> new RuntimeException("Rol no encontrado"));

        UserEntity user = new UserEntity();
        user.setName(dto.getName());
        user.setLastName(dto.getLastName());
        user.setEmail(dto.getEmail());
        user.setNumber(dto.getNumber());

        user.setPassword(hashedPassword);
        user.setRole(role);

        DoctorProfileEntity profile = new DoctorProfileEntity();
        profile.setLicenseNumber(dto.getLicenseNumber());
        profile.setCountry(country);
        profile.setLicenseImageUrl(imageUrl);
        profile.setUser(user);
        user.setStatus(AccountStatusENUM.ACTIVE);
        user.setDoctorProfile(profile);

        DoctorApplicationsEntity doctorApplication = new DoctorApplicationsEntity();
        doctorApplication.setStatus(ProcessStatusENUM.PENDING);
        doctorApplication.setRead(false);
        doctorApplication.setDoctor(user);
        doctorApplicationsRepository.save(doctorApplication);

        return userRepository.save(user);
    }

