#workspaces button {
    all: unset;

    /* 1. EL TAMAÑO DE TU "DIV" */
    min-width: 6px;       /* Qué tan gruesa es la línea */
    min-height: 25px;     /* Qué tan larga es la línea */

    /* 2. LA FORMA Y EL COLOR */
    background-color: alpha(@color1, 0.4); /* Color de fondo, no color de texto */
    border-radius: 10px;  /* Para que las puntas sean redondeadas (opcional) */

    /* 3. EL ESPACIADO ENTRE ELLOS */
    margin-top: 5px;      /* Espacio arriba de cada "línea" */
    margin-bottom: 5px;   /* Espacio abajo */
    margin-left: 0px;     /* Pegado a la izquierda */

    transition: all 0.3s cubic-bezier(.55,-0.68,.48,1.68); /* Animación suave */
}

/* Cuando estás en ese espacio de trabajo */
#workspaces button.active {
    background-color: @color1;
    min-height: 40px; /* ¡Puedes hacer que se estire cuando está activo! */
    box-shadow: 0px 0px 5px rgba(0, 0, 0, 0.5); /* Sombra para resaltar */
}

/* Cuando el espacio está vacío */
#workspaces button.empty {
    background-color: alpha(#ffffff, 0.2);
    min-height: 15px; /* Más cortito si está vacío */
}

/* Efecto al pasar el mouse */
#workspaces button:hover {
    background-color: @color3;
    min-height: 35px;
}

